# --- rebase --------------------------------------------------------------------------------

if wanted rebase; then
    case_ "rebase: onto main" fx_branches 'git checkout -q feat' 'G rebase main'
    case_ "rebase: -q" fx_branches 'git checkout -q feat' 'G rebase -q main'
    case_ "rebase: up to date" fx_branches 'git checkout -q feat; git rebase -q main' 'G rebase main'
    case_ "rebase: fast-forward" fx_base 'git switch -q side' 'G rebase main'
    case_ "rebase: --force-rebase on an up to date branch" fx_branches 'git checkout -q feat; git rebase -q main' 'G rebase --force-rebase main'
    case_ "rebase: branch as the second argument" fx_branches ':' 'G rebase main feat'
    case_ "rebase: --onto" fx_branches 'git checkout -q feat' 'G rebase --onto main feat~2'
    case_ "rebase: --onto with a branch" fx_branches ':' 'G rebase --onto main feat~2 feat'
    case_ "rebase: --onto dropping the first commits" fx_branches 'git checkout -q feat' 'G rebase --onto main~1 feat~1'
    case_ "rebase: --keep-base" fx_branches 'git checkout -q feat' 'G rebase --keep-base main'
    case_ "rebase: --root" fx_branches 'git checkout -q feat' 'G rebase --root --onto main'
    case_ "rebase: --root with no onto" fx_branches 'git checkout -q feat' 'G rebase --root'
    case_ "rebase: detached HEAD" fx_branches 'git checkout -q --detach feat' 'G rebase main'
    case_ "rebase: no upstream" fx_branches 'git checkout -q feat' 'G rebase'
    case_ "rebase: upstream configured" fx_branches 'git checkout -q feat; git config branch.feat.remote .; git config branch.feat.merge refs/heads/main' 'G rebase'
    case_ "rebase: bad upstream" fx_branches 'git checkout -q feat' 'G rebase nope'
    case_ "rebase: dirty work tree" fx_branches 'git checkout -q feat; echo x >> f.txt' 'G rebase main'
    case_ "rebase: staged changes" fx_branches 'git checkout -q feat; echo x >> f.txt; git add f.txt' 'G rebase main'
    case_ "rebase: --autostash" fx_branches 'git checkout -q feat; echo x >> n.txt' 'G rebase --autostash main'
    case_ "rebase: --autostash conflicting" fx_branches 'git checkout -q feat; echo x >> f.txt' 'G rebase --autostash main'
    case_ "rebase: rebase.autoStash" fx_branches 'git checkout -q feat; echo x >> n.txt; git config rebase.autoStash true' 'G rebase main'
    case_ "rebase: conflict" fx_branches 'git checkout -q clash' 'G rebase main'
    case_ "rebase: conflict then continue" fx_branches 'git checkout -q clash; git rebase main; printf "R\n" > h.txt; git add h.txt' 'GIT_EDITOR=true G rebase --continue'
    case_ "rebase: conflict then continue unresolved" fx_branches 'git checkout -q clash; git rebase main' 'GIT_EDITOR=true G rebase --continue'
    case_ "rebase: conflict then abort" fx_branches 'git checkout -q clash; git rebase main' 'G rebase --abort'
    case_ "rebase: conflict then skip" fx_branches 'git checkout -q clash; git rebase main' 'G rebase --skip'
    case_ "rebase: conflict then quit" fx_branches 'git checkout -q clash; git rebase main' 'G rebase --quit'
    case_ "rebase: second commit conflicts" fx_branches 'git checkout -q clash; echo more > m2.txt; git add m2.txt; git commit -qm "clash: m2"; printf "CLASH\nlast\n" > h.txt; git commit -qam "clash: h2"; git rebase main; printf "R\n" > h.txt; git add h.txt; GIT_EDITOR=true git rebase --continue' 'GIT_EDITOR=true G rebase --continue; G status'
    case_ "rebase: nothing in progress" fx_branches ':' 'G rebase --continue; G rebase --abort; G rebase --skip'
    case_ "rebase: already rebasing" fx_branches 'git checkout -q clash; git rebase main' 'G rebase main'
    case_ "rebase: commit that becomes empty is dropped" fx_branches 'git checkout -q feat; git cherry-pick main~0 >/dev/null 2>&1; git cherry-pick --abort 2>/dev/null; git checkout -q main; git cherry-pick feat~2 >/dev/null; git checkout -q feat' 'G rebase main'
    case_ "rebase: diff3 conflict style" fx_branches 'git checkout -q clash; git config merge.conflictStyle diff3' 'G rebase main'
    case_ "rebase: -i untouched" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR=true G rebase -i main'
    case_ "rebase: -i drop" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak 2s/^pick/drop/" G rebase -i main'
    case_ "rebase: -i reorder" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak -e 1{h;d} -e 2{G}" G rebase -i main'
    case_ "rebase: -i squash" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak 2s/^pick/squash/" GIT_EDITOR=true G rebase -i main'
    case_ "rebase: -i fixup" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak 2s/^pick/fixup/" GIT_EDITOR=false G rebase -i main'
    case_ "rebase: -i fixup chain" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak -e 2s/^pick/fixup/ -e 3s/^pick/fixup/" GIT_EDITOR=false G rebase -i main'
    case_ "rebase: -i reword" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak 2s/^pick/reword/" GIT_EDITOR="sed -i.bak 1s/^/reworded:/" G rebase -i main'
    case_ "rebase: -i edit then continue" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak 2s/^pick/edit/" G rebase -i main; G status; G rebase --continue'
    case_ "rebase: -i edit and amend" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak 2s/^pick/edit/" G rebase -i main; echo amended > am.txt; G add am.txt; G commit -q --amend --no-edit; G rebase --continue'
    case_ "rebase: -i exec" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak 2a\\exec\ true" G rebase -i main'
    case_ "rebase: -i exec failing" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak 2a\\exec\ false" G rebase -i main; G status; G rebase --continue'
    case_ "rebase: -i break" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak 2a\\break" G rebase -i main; G rebase --continue'
    case_ "rebase: -x" fx_branches 'git checkout -q feat' 'G rebase -x true main'
    case_ "rebase: -x failing" fx_branches 'git checkout -q feat' 'G rebase -x false main; G rebase --abort'
    case_ "rebase: --edit-todo" fx_branches 'git checkout -q feat; GIT_SEQUENCE_EDITOR="sed -i.bak 1s/^pick/edit/" git rebase -i main' 'GIT_SEQUENCE_EDITOR="sed -i.bak 1s/^pick/drop/" G rebase --edit-todo; G rebase --continue'
    case_ "rebase: -i empty todo" fx_branches 'git checkout -q feat' 'GIT_SEQUENCE_EDITOR="sed -i.bak /^pick/d" G rebase -i main'
    case_ "rebase: -i with conflict then continue" fx_branches 'git checkout -q clash; GIT_SEQUENCE_EDITOR=true git rebase -i main; printf "R\n" > h.txt; git add h.txt' 'GIT_EDITOR=true G rebase --continue'
    case_ "rebase: --autosquash" fx_branches 'git checkout -q feat; echo fx >> g.txt; git commit -q -a --fixup feat~2; echo fy >> f.txt; git commit -q -a --fixup feat~1' 'GIT_SEQUENCE_EDITOR=true G rebase -i --autosquash main'
    case_ "rebase: --autosquash with squash!" fx_branches 'git checkout -q feat; echo fx >> g.txt; git commit -q -a --squash feat~2 -m "extra words"' 'GIT_SEQUENCE_EDITOR=true GIT_EDITOR=true G rebase -i --autosquash main'
    case_ "rebase: rebase.autoSquash" fx_branches 'git checkout -q feat; echo fx >> g.txt; git commit -q -a --fixup feat~2; git config rebase.autoSquash true' 'GIT_SEQUENCE_EDITOR=true G rebase -i main'
    case_ "rebase: --no-autosquash" fx_branches 'git checkout -q feat; echo fx >> g.txt; git commit -q -a --fixup feat~2; git config rebase.autoSquash true' 'GIT_SEQUENCE_EDITOR=true G rebase -i --no-autosquash main'
    case_ "rebase: --autosquash without -i" fx_branches 'git checkout -q feat; echo fx >> g.txt; git commit -q -a --fixup feat~2' 'G rebase --autosquash main'
    case_ "rebase: reflog of the branch" fx_branches 'git checkout -q feat' 'G rebase main; git reflog -3'
    case_ "rebase: ORIG_HEAD" fx_branches 'git checkout -q feat' 'G rebase main; git rev-parse ORIG_HEAD'
    case_ "rebase: merge commits are flattened" fx_mergecommit 'git checkout -q -b topic other' 'G rebase main'
    case_ "rebase: renamed file in the range" fx_rbase 'git checkout -q other; git mv a.txt moved.txt; git commit -qm mv; git checkout -q main; echo more >> a.txt; git commit -qam edit; git checkout -q other' 'G rebase main'
fi
